  click(settingsBtn, () => showView('settings'));
  click(one('overview-nav-item', panel), () => main.scrollTo({ top: 0, behavior: 'smooth' }), 'proto-hover');
  click(one('my-work-nav-item', panel), () => { const c = one('my-work-card', app); if (c) scrollTo(c); }, 'proto-hover');
  click(one('open-monitoring-button', app), () => { const c = one('monitoring-exceptions-card', app); if (c) scrollTo(c); }, 'proto-hover');
  click(one('open-monitoring-link', app), () => { const c = one('monitoring-exceptions-card', app); if (c) scrollTo(c); }, 'proto-link');
  click(one('open-validate-analytics-link', app), () => { const c = one('model-performance-header', app); if (c) scrollTo(c); }, 'proto-link');
  click(one('all-7-link', app), () => { const c = one('my-work-card', app); if (c) scrollTo(c); }, 'proto-link');
